function drawSpider(sp,x,y,scale=1,face='left',frame=0){
 let c=sp.color,d=sp.dark,s=scale;
 rect(x-24*s,y+17*s,49*s,5*s,'#425c3b66');
 ctx.strokeStyle=d;ctx.lineWidth=Math.max(2,3*s);ctx.lineCap='square';
 for(let i=0;i<4;i++){let yy=y-9*s+i*6*s, ext=(i===0||i===3?17:21)*s, wig=(frame%2?2:-1)*s;ctx.beginPath();ctx.moveTo(x-12*s,yy);ctx.lineTo(x-ext,yy-9*s+wig);ctx.lineTo(x-(ext+5*s),yy-4*s+wig);ctx.moveTo(x+12*s,yy);ctx.lineTo(x+ext,yy-9*s-wig);ctx.lineTo(x+(ext+5*s),yy-4*s-wig);ctx.stroke()}
 ctx.fillStyle=d;ctx.beginPath();ctx.ellipse(x,y+1*s,15*s,12*s,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(x+(face==='left'?7:-7)*s,y+1*s,10*s,9*s,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=c;ctx.beginPath();ctx.arc(x+(face==='left'?-10:10)*s,y-5*s,9*s,0,Math.PI*2);ctx.fill();
 rect(x+(face==='left'?-13:9)*s,y-7*s,3*s,3*s,'#fff2d5');rect(x+(face==='left'?-12:10)*s,y-7*s,1.5*s,2*s,'#27352d');
 if(sp.name==='Emberling'){rect(x-5*s,y-6*s,3*s,3*s,'#f6cf73');rect(x-3*s,y+1*s,9*s,2*s,'#f3c477')}
 if(sp.name==='Fernweaver'){rect(x-5*s,y-4*s,8*s,3*s,'#d7e08f');rect(x-7*s,y+2*s,12*s,2*s,'#c7d782')}
 if(sp.name==='Moonspinner'){rect(x-4*s,y-7*s,2*s,2*s,'#f2e5ad');rect(x-7*s,y+1*s,12*s,2*s,'#e3dbef')}
