function updateRoster(){let host=document.getElementById('roster');host.innerHTML='';document.getElementById('partyCount').textContent=`${party.length.toString().padStart(2,'0')} / 06`;party.slice(0,6).forEach(p=>{let row=document.createElement('div');row.className='roster-row';row.innerHTML=`<div class="roster-icon">🕸️</div><div style="min-width:0"><div class="roster-name">${p.name}</div><div class="roster-meta">${p.kind} · Lv ${p.level||3}</div><div class="mini-progress"><i style="width:${Math.max(0,p.hp/p.max*100)}%"></i></div></div><div class="roster-hp">${p.hp}/${p.max}</div>`;host.appendChild(row)})}
function render(){ctx.clearRect(0,0,W,H);if(state==='battle'||state==='battleMenu')drawBattle();else if(state==='menu')drawMenu();else drawWorld();requestAnimationFrame(render)}
function startMusic(){if(!music||beatTimer)return;try{audioCtx=audioCtx||new (window.AudioContext||window.webkitAudioContext)();audioCtx.resume();let melody=[523,659,784,659,587,698,880,698,523,659,784,988,880,784,659,587],bass=[131,165,147,196,131,175,147,196],i=0;beatTimer=setInterval(()=>{if(!music||!audioCtx)return;let now=audioCtx.currentTime;function note(freq,dur,type,vol){let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(vol,now+.025);g.gain.exponentialRampToValueAtTime(.0001,now+dur);o.connect(g);g.connect(audioCtx.destination);o.start(now);o.stop(now+dur+.02)}note(melody[i%melody.length],.22,'square',.025);if(i%2===0)note(bass[Math.floor(i/2)%bass.length],.34,'triangle',.04);if(i%4===0)note(1175,.055,'sine',.009);i++},270)}catch(e){console.warn('Audio unavailable',e)}}
function stopMusic(){if(beatTimer){clearInterval(beatTimer);beatTimer=null}if(audioCtx)audioCtx.suspend()}
function toggleMusic(){music=!music;document.getElementById('soundBtn').textContent=music?'♫ Sound on':'♫ Sound off';if(music)startMusic();else stopMusic()}
function perform(key){if(key==='confirm')confirm();else if(key==='cancel')back();else if(key==='up')moveCursor(0,-1);else if(key==='down')moveCursor(0,1);else if(key==='left')moveCursor(-1,0);else if(key==='right')moveCursor(1,0);startMusic()}
const dirKey={ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down',ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right'};
window.addEventListener('keydown',e=>{let k=e.key;if(dirKey[k]){e.preventDefault();if(!keys[k])perform(dirKey[k]);keys[k]=true;return}if(e.repeat)return;if(k==='Enter'||k===' '||k==='z'||k==='Z'){e.preventDefault();perform('confirm')}else if(k==='Escape'||k==='Backspace'||k==='x'||k==='X'){e.preventDefault();perform('cancel')}else if(k==='1'||k==='2'||k==='3'||k==='4'){selected=Number(k)-1;confirm()}else if(k==='Tab'){e.preventDefault();openMenu()}});
window.addEventListener('keyup',e=>{delete keys[e.key]});
setInterval(()=>{for(let k in keys){if(dirKey[k])perform(dirKey[k])}},165);
document.querySelectorAll('[data-dir]').forEach(b=>{let interval;const release=()=>{clearInterval(interval);interval=null};b.addEventListener('pointerdown',e=>{e.preventDefault();startMusic();perform(b.dataset.dir);interval=setInterval(()=>perform(b.dataset.dir),165)});['pointerup','pointerleave','pointercancel'].forEach(ev=>b.addEventListener(ev,release))});
document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();perform(b.dataset.action)}));
document.getElementById('soundBtn').addEventListener('click',toggleMusic);
document.getElementById('menuBtn').addEventListener('click',()=>{openMenu();startMusic()});
updateRoster();render();
</script>
</body>
</html>

